/bin/bash -lc "cat > /tmp/gen189.py <<'PY'
import re
src=open('/workspace/Language.v').read()
allcons={}
for ty in ('tm','brs','co','constraint'):
 s=re.search(r'(?:Inductive|with) '+ty+r' : Set :=["'^'"\\n]*\\n(.*?)(?=\\nwith |\\.\\n)',src,re.S)[1]
 cons=[]
 for l in s.splitlines():
  c=re.search(r'\\| (\\w+)(.*)',l)
  if c:
   name,args=c.groups()
   args=[(n if n"'!='"'_' else 'n',t) for n,t in re.findall(r'\\((\\w+):(\\w+)\\)',args)]
   cons.append((name,args))
 allcons[ty]=cons
# binder depths are inherited from the supplied opening functions
bind_tm={('a_Abs','b'),('a_UAbs','b'),('a_Pi','B'),('g_PiCong','g2'),('g_AbsCong','g2')}
bind_co={('a_CPi','B'),('a_CAbs','b'),('a_UCAbs','b'),('g_CPiCong','g3'),('g_CAbsCong','g3')}
def emit(prefix,params,ret,default,overrides):
 for i,(ty,cons) in enumerate(allcons.items()):
  print(f'{\"Fixpoint\" if not i else \"with\"} {prefix}_{ty} {params} (s : {ty}) {{struct s}} : {ret if ret else ty} :=\\n  match s with')
  for c,args in cons:
   vs=' '.join(n for n,t in args)
   kids=[(n,t, '(S i)' if (c,n) in bind_tm else 'i', '(S j)' if (c,n) in bind_co else 'j') for n,t in args if t in allcons]
   rhs=overrides[c] if c in overrides else default(prefix,c,args,kids)
   print('  | '+c+(' '+vs if vs else '')+' => '+rhs)
  print('  end'+('.\\n' if i==3 else ''))
def syn(pre,c,args,kids):
 mp={n:f'({pre}_{t} f_t f_c b_t b_c {i} {j} {n})' for n,t,i,j in kids}
 return ' '.join([c]+[mp.get(n,n) for n,t in args])
emit('task_walk','(f_t f_c : nat -> atom -> _) (b_t b_c : nat -> nat -> _) (i j : nat)',None,syn,{'a_Var_f':'f_t i x','a_Var_b':'b_t i n','g_Var_f':'f_c j c','g_Var_b':'b_c j n'})
def sc(pre,c,args,kids):
 return ' /\\\\ '.join(f'{pre}_{t} {i} {j} {n}' for n,t,i,j in kids) or 'True'
emit('task_scope','(i j : nat)','Prop',sc,{'a_Var_b':'n < i','g_Var_b':'n < j'})
def fv(pre,c,args,kids):
 return ' \\\\u '.join(f'{pre}_{t} {n}' for n,t,i,j in kids) or 'empty'
emit('task_vars','','atoms',fv,{'a_Var_f':'singleton x','g_Var_f':'singleton c','a_Fam':'singleton F'})
PY
