cat > /tmp/gen_algebra189.py <<'PY'
import sys
tys=['tm','brs','co','constraint']
def mutual(name,statement,tac):
 print('Lemma '+name+' :')
 print(' /\\\\\\n'.join('  (forall s '+statement(t)+')' for t in tys)+'.')
 print('Proof.\\n  '+tac+'\\nQed.\\n')
for v in ('t','c'):
 ix='i' if v=='t' else 'j'
 typ='tm' if v=='t' else 'co'
 mutual('task_scope_idle_'+v,
  lambda t: f'i j (u : {typ}), task_scope_{t} i j s -> open_{t}_wrt_{\"tm\" if v==\"t\" else \"co\"}_rec {ix} u s = s',
  '''task_structure; intros; cbn in *; task_break_and;
  try solve [f_equal; auto];
  match goal with |- context [lt_eq_lt_dec ?n ?k] =>
    destruct (lt_eq_lt_dec n k) as [[?|?]|?]; try reflexivity; lia
  end.''')
print('''Record task_substitution := {
  task_ft : atom -> tm;
  task_fc : atom -> co;
  task_ft_scope : forall x, task_scope_tm 0 0 (task_ft x);
  task_fc_scope : forall x, task_scope_co 0 0 (task_fc x);
  task_support : atoms;
  task_ft_fresh : forall x, x "'`notin` task_support -> task_ft x = a_Var_f x;
  task_fc_fresh : forall x, x `notin` task_support -> task_fc x = g_Var_f x;
  task_ft_vars : forall x y, y `notin` task_support ->
                      y `in` task_vars_tm (task_ft x) -> x = y;
  task_fc_vars : forall x y, y `notin` task_support ->
                      y `in` task_vars_co (task_fc x) -> x = y
}.'"''')
for t in tys:
 print(f'Definition task_sub_{t} S := task_walk_{t} (fun _ => task_ft S) (fun _ => task_fc S) task_id_bt task_id_bc 0 0.')
mutual('task_sub_walk_depth',lambda t:f'S i j k l, task_walk_{t} (fun _ => task_ft S) (fun _ => task_fc S) task_id_bt task_id_bc i j s = task_walk_{t} (fun _ => task_ft S) (fun _ => task_fc S) task_id_bt task_id_bc k l s',
  'task_structure; intros; cbn; f_equal; auto.')
for t in tys:
 print(f'Lemma task_sub_{t}_walk : forall S i j s, task_walk_{t} (fun _ => task_ft S) (fun _ => task_fc S) task_id_bt task_id_bc i j s = task_sub_{t} S s.')
 print('Proof. intros; unfold task_sub_'+t+'; apply task_sub_walk_depth. Qed.')
print('''#[local] Hint Rewrite task_sub_tm_walk task_sub_brs_walk task_sub_co_walk
  task_sub_constraint_walk : task_sub.''')
mutual('task_sub_scope',
  lambda t:f'S i j, task_scope_{t} i j s -> task_scope_{t} i j (task_sub_{t} S s)',
  '''pose proof task_scope_mono as [MT [_ [MC _]]].
  task_structure; intros; cbn in *; autorewrite with task_sub; task_break_and;
  task_split_and; auto;
  first [eapply MT; [lia | lia | apply task_ft_scope]
        |eapply MC; [lia | lia | apply task_fc_scope]].''')
for v in ('t','c'):
 ix='i' if v=='t' else 'j'
 op='tm' if v=='t' else 'co'
 mutual('task_sub_open_'+v+'_rec',lambda t: f'S k (u : {op}), task_sub_{t} S (open_{t}_wrt_{op}_rec k u s) = open_{t}_wrt_{op}_rec k (task_sub_{op} S u) (task_sub_{t} S s)',
  f'''pose proof task_scope_idle_{v} as [IT [_ [IC _]]].
  pose proof task_scope_mono as [MT [_ [MC _]]].
  task_structure; intros; cbn; autorewrite with task_sub;
  try solve [f_equal; auto];
  first
    [symmetry; apply (IT _ {\"k 0\" if v==\"t\" else \"0 k\"}); eapply MT; [lia | lia | apply task_ft_scope]
    |symmetry; apply (IC _ {\"k 0\" if v==\"t\" else \"0 k\"}); eapply MC; [lia | lia | apply task_fc_scope]
    |match goal with |- context [lt_eq_lt_dec ?n ?k] =>
       destruct (lt_eq_lt_dec n k) as [[?|?]|?]; reflexivity
     end].''')
